import React, { useState } from 'react';

interface NavbarProps {
  activeSection: string;
  isProjectView?: boolean;
  onNavigateHome?: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ activeSection, isProjectView, onNavigateHome }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const links = [
    { name: 'Home', href: '#home', id: 'home' },
    { name: 'About', href: '#about', id: 'about' },
    { name: 'Projects', href: '#projects', id: 'projects' },
    { name: 'Contact', href: '#contact', id: 'contact' },
  ];

  const handleNavigation = (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>, id: string) => {
    e.preventDefault();

    // If we are on a project detail page, we need to go back to home first
    if (isProjectView && onNavigateHome) {
      onNavigateHome();
      // Use a timeout to wait for the home view to mount before scrolling
      setTimeout(() => scrollToId(id), 50);
    } else {
      scrollToId(id);
    }

    setIsMenuOpen(false);
  };

  const scrollToId = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 64; // Navbar height
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    } else if (id === 'home') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 glass border-b border-gray-100 transition-all duration-300">
      <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
        <div 
          className="flex items-center gap-2 group cursor-pointer" 
          onClick={(e) => handleNavigation(e as any, 'home')}
        >
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 text-primary transition-colors group-hover:bg-primary group-hover:text-white">
            <span className="material-symbols-outlined text-xl font-bold">design_services</span>
          </div>
          <span className="text-lg font-bold tracking-tight text-neutral-text">Patricia Eziashi</span>
        </div>

        {/* Desktop Links */}
        <div className="hidden md:flex items-center gap-2">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.href}
              onClick={(e) => handleNavigation(e, link.id)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${
                activeSection === link.id
                  ? 'bg-primary/10 text-primary'
                  : 'text-gray-600 hover:text-primary hover:bg-primary/5'
              }`}
            >
              {link.name}
            </a>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={(e) => handleNavigation(e as any, 'contact')}
            className="hidden md:block rounded-full bg-primary px-6 py-2.5 text-sm font-bold text-white shadow-lg shadow-primary/25 transition-all hover:-translate-y-0.5 hover:shadow-primary/40 active:translate-y-0"
          >
            Let's Talk
          </button>
          <button 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="flex md:hidden h-10 w-10 items-center justify-center rounded-lg text-gray-600 hover:bg-gray-100 transition-colors"
          >
            <span className="material-symbols-outlined">
              {isMenuOpen ? 'close' : 'menu'}
            </span>
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden absolute top-16 left-0 right-0 bg-white border-b border-gray-100 transition-all duration-300 overflow-hidden ${isMenuOpen ? 'max-h-[32rem] py-4 opacity-100 shadow-xl' : 'max-h-0 py-0 opacity-0'}`}>
        <div className="flex flex-col px-6 gap-2">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.href}
              onClick={(e) => handleNavigation(e, link.id)}
              className={`px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                activeSection === link.id
                  ? 'bg-primary/10 text-primary'
                  : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              {link.name}
            </a>
          ))}
          <button
            onClick={(e) => handleNavigation(e as any, 'contact')}
            className="mt-4 block w-full text-center rounded-xl bg-primary py-4 text-sm font-bold text-white shadow-lg shadow-primary/20 active:scale-[0.98] transition-transform"
          >
            Let's Talk
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';

interface NavbarProps {
  activeSection: string;
  isProjectView?: boolean;
  onNavigateHome?: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ activeSection, isProjectView, onNavigateHome }) => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const links = [
    { name: 'Home', href: '#home', id: 'home' },
    { name: 'About', href: '#about', id: 'about' },
    { name: 'Projects', href: '#projects', id: 'projects' },
    { name: 'Contact', href: '#contact', id: 'contact' },
  ];

  const handleNavigation = (e: React.MouseEvent<HTMLAnchorElement | HTMLButtonElement>, id: string) => {
    e.preventDefault();

    // If we are on a project detail page, we need to go back to home first
    if (isProjectView && onNavigateHome) {
      onNavigateHome();
      // Use a timeout to wait for the home view to mount before scrolling
      setTimeout(() => scrollToId(id), 50);
    } else {
      scrollToId(id);
    }

    setIsMenuOpen(false);
  };

  const scrollToId = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 64; // Navbar height
      const bodyRect = document.body.getBoundingClientRect().top;
      const elementRect = element.getBoundingClientRect().top;
      const elementPosition = elementRect - bodyRect;
      const offsetPosition = elementPosition - offset;

      window.scrollTo({
        top: offsetPosition,
        behavior: 'smooth'
      });
    } else if (id === 'home') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <nav className="fixed top-0 left-0 right-0 z-50 glass border-b border-gray-100 transition-all duration-300">
      <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
        <div 
          className="flex items-center group cursor-pointer" 
          onClick={(e) => handleNavigation(e as any, 'home')}
        >
          <span className="text-lg font-bold tracking-tight text-neutral-text transition-colors group-hover:text-primary">
            Patricia Eziashi
          </span>
        </div>

        {/* Desktop Links */}
        <div className="hidden md:flex items-center gap-2">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.href}
              onClick={(e) => handleNavigation(e, link.id)}
              className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-300 ${
                activeSection === link.id
                  ? 'bg-primary/10 text-primary'
                  : 'text-gray-600 hover:text-primary hover:bg-primary/5'
              }`}
            >
              {link.name}
            </a>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={(e) => handleNavigation(e as any, 'contact')}
            className="hidden md:block rounded-full bg-primary px-6 py-2.5 text-sm font-bold text-white shadow-lg shadow-primary/25 transition-all hover:-translate-y-0.5 hover:shadow-primary/40 active:translate-y-0"
          >
            Let's Talk
          </button>
          <button 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="flex md:hidden h-10 w-10 items-center justify-center rounded-lg text-gray-600 hover:bg-gray-100 transition-colors"
          >
            <span className="material-symbols-outlined">
              {isMenuOpen ? 'close' : 'menu'}
            </span>
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      <div className={`md:hidden absolute top-16 left-0 right-0 bg-white border-b border-gray-100 transition-all duration-300 overflow-hidden ${isMenuOpen ? 'max-h-[32rem] py-4 opacity-100 shadow-xl' : 'max-h-0 py-0 opacity-0'}`}>
        <div className="flex flex-col px-6 gap-2">
          {links.map((link) => (
            <a
              key={link.id}
              href={link.href}
              onClick={(e) => handleNavigation(e, link.id)}
              className={`px-4 py-3 rounded-xl text-sm font-bold transition-all ${
                activeSection === link.id
                  ? 'bg-primary/10 text-primary'
                  : 'text-gray-600 hover:bg-gray-50'
              }`}
            >
              {link.name}
            </a>
          ))}
          <button
            onClick={(e) => handleNavigation(e as any, 'contact')}
            className="mt-4 block w-full text-center rounded-xl bg-primary py-4 text-sm font-bold text-white shadow-lg shadow-primary/20 active:scale-[0.98] transition-transform"
          >
            Let's Talk
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState } from 'react';
import { PROJECTS, CERTIFICATES, TECH_STACK } from '../constants';
import { TabType, Project } from '../types';
import { useIntersectionObserver } from '../hooks/useIntersectionObserver';

interface PortfolioShowcaseProps {
  onSelectProject?: (id: string) => void;
}

const PortfolioShowcase: React.FC<PortfolioShowcaseProps> = ({ onSelectProject }) => {
  const [activeTab, setActiveTab] = useState<TabType>(TabType.PROJECTS);
  const [isAnimating, setIsAnimating] = useState(false);
  const [ref, isVisible] = useIntersectionObserver({ threshold: 0.1, triggerOnce: true });

  const tabs = Object.values(TabType);

  const handleTabChange = (tab: TabType) => {
    if (tab === activeTab) return;
    setIsAnimating(true);
    setTimeout(() => {
      setActiveTab(tab);
      setIsAnimating(false);
    }, 200);
  };

  const renderProjectCard = (project: Project) => {
    // Check if this is the Finance Dashboard (Featured horizontal card)
    const isFeatured = project.id === '2';

    if (isFeatured) {
      return (
        <div key={project.id} className="col-span-full group relative bg-[#f9fafb] rounded-[2.5rem] overflow-hidden border border-gray-100 p-8 lg:p-12 transition-all hover:border-primary/20 hover:shadow-2xl hover:shadow-primary/5 flex flex-col lg:flex-row items-center gap-12 mb-8">
          <div className="lg:w-1/2">
            <span className="inline-block px-4 py-1.5 bg-primary/10 text-primary text-[10px] font-black uppercase tracking-[0.2em] rounded-full mb-6">
              {project.badge || 'Case Study'}
            </span>
            <h3 className="text-3xl lg:text-5xl font-serif font-black text-neutral-text mb-6 group-hover:text-primary transition-colors">
              {project.title}
            </h3>
            <p className="text-lg text-gray-500 leading-relaxed mb-10 max-w-xl">
              {project.description}
            </p>
            <div className="flex flex-wrap gap-4">
              <button 
                onClick={() => onSelectProject?.(project.id)}
                className="bg-primary text-white px-8 py-3.5 rounded-xl font-bold shadow-lg shadow-primary/20 hover:-translate-y-1 transition-all text-sm"
              >
                View Case Study
              </button>
              <button className="bg-white text-gray-600 px-8 py-3.5 rounded-xl font-bold hover:bg-gray-50 transition-all border border-gray-200 shadow-sm text-sm">
                Read Process
              </button>
            </div>
          </div>
          <div className="lg:w-1/2 relative">
            <div className="absolute inset-0 bg-primary/5 rounded-[2rem] rotate-2 -z-10 group-hover:rotate-1 transition-transform"></div>
            <img 
              src={project.image} 
              alt={project.title} 
              className="rounded-[2rem] shadow-xl w-full object-cover aspect-[16/10]" 
            />
          </div>
        </div>
      );
    }

    // Standard Grid Card
    return (
      <div key={project.id} className="group relative bg-neutral-background rounded-[2.5rem] overflow-hidden border border-gray-100 transition-all hover:border-primary/20 hover:shadow-2xl hover:shadow-primary/10">
        <div className="aspect-[16/10] overflow-hidden relative">
          <img src={project.image} alt={project.title} className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-110" />
          {project.badge && (
            <div className="absolute top-6 right-6 px-4 py-1.5 bg-white/95 backdrop-blur shadow-sm rounded-full z-10 border border-primary/20">
              <span className="text-[10px] font-black uppercase tracking-widest text-primary animate-pulse-soft">
                {project.badge}
              </span>
            </div>
          )}
        </div>
        <div className="p-8">
          <div className="flex gap-2 mb-4">
            {project.tags.map(tag => (
              <span key={tag} className="px-3 py-1 bg-primary/10 text-primary text-[10px] font-bold uppercase tracking-wider rounded-full">{tag}</span>
            ))}
          </div>
          <h3 className="text-2xl font-black text-neutral-text mb-2 group-hover:text-primary transition-colors">{project.title}</h3>
          <p className="text-gray-500 leading-relaxed mb-8">{project.description}</p>
          <div className="flex gap-4">
            <button 
              onClick={() => onSelectProject?.(project.id)}
              className="bg-primary text-white px-6 py-2.5 rounded-lg font-bold shadow-md shadow-primary/10 hover:-translate-y-1 transition-all text-xs"
            >
              Case Study
            </button>
            <button className="bg-white text-gray-500 px-6 py-2.5 rounded-lg font-bold hover:bg-gray-50 transition-all border border-gray-200 text-xs">
              Live Site
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <section ref={ref} className="py-24 bg-white">
      <div className="max-w-7xl mx-auto px-6">
        <div className={`text-center mb-16 transition-all duration-1000 transform ${isVisible ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0'}`}>
          <span className="text-primary font-bold uppercase tracking-widest text-sm mb-4 block">Selected Works</span>
          <h2 className="text-4xl lg:text-5xl font-black text-neutral-text">Portfolio Showcase</h2>
        </div>

        {/* Tab Navigation */}
        <div className="flex justify-center mb-16 overflow-x-auto pb-4 no-scrollbar">
          <div className="inline-flex p-1.5 bg-neutral-background rounded-2xl border border-gray-100 shadow-sm relative whitespace-nowrap">
            {tabs.map((tab) => (
              <button
                key={tab}
                onClick={() => handleTabChange(tab)}
                className={`relative px-6 sm:px-8 py-3 rounded-xl text-sm font-bold transition-all duration-300 z-10 ${
                  activeTab === tab ? 'text-white' : 'text-gray-500 hover:text-primary'
                }`}
              >
                {tab}
                {activeTab === tab && (
                  <div className="absolute inset-0 bg-primary rounded-xl -z-10 shadow-lg shadow-primary/30 animate-in fade-in zoom-in-95 duration-200"></div>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* Content Area */}
        <div className={`min-h-[600px] relative transition-opacity duration-200 ${isAnimating ? 'opacity-0 scale-[0.98]' : 'opacity-100 scale-100'}`}>
          {activeTab === TabType.PROJECTS && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              {PROJECTS.map((project) => renderProjectCard(project))}
            </div>
          )}

          {activeTab === TabType.CERTIFICATES && (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              {CERTIFICATES.map((cert) => (
                <div key={cert.id} className="p-8 bg-neutral-background rounded-[2rem] border border-gray-100 transition-all hover:-translate-y-2 hover:shadow-xl hover:shadow-primary/10 group">
                  <div className="h-14 w-14 flex items-center justify-center rounded-2xl bg-white text-primary mb-6 shadow-sm group-hover:bg-primary group-hover:text-white transition-colors">
                    <span className="material-symbols-outlined text-3xl">{cert.icon}</span>
                  </div>
                  <h3 className="text-xl font-bold text-neutral-text mb-2">{cert.title}</h3>
                  <p className="text-gray-500 font-medium mb-1">{cert.issuer}</p>
                  <p className="text-sm text-gray-400 mb-6">{cert.year}</p>
                  <a href={cert.link} className="text-sm font-bold text-primary hover:underline underline-offset-4">View Certificate</a>
                </div>
              ))}
            </div>
          )}

          {activeTab === TabType.TECH_STACK && (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
              {TECH_STACK.map((tech) => (
                <div key={tech.name} className="flex flex-col items-center justify-center p-8 bg-neutral-background rounded-[2rem] border border-transparent hover:border-primary/20 hover:bg-white transition-all hover:shadow-lg group">
                  <div className={`mb-4 transition-transform group-hover:scale-110 group-hover:animate-bounce ${tech.color}`}>
                    <span className="material-symbols-outlined text-5xl">{tech.icon}</span>
                  </div>
                  <span className="font-bold text-gray-700 text-sm group-hover:text-primary transition-colors text-center">{tech.name}</span>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default PortfolioShowcase;
